use std::sync::mpsc;
use std::thread;

fn chunk_size(len: usize, threads: usize) -> usize {
    assert!(threads > 0, "need at least one thread");
    len.div_ceil(threads).max(1)
}

fn parallel_sum(data: &[u64], threads: usize) -> u64 {
    let size = chunk_size(data.len(), threads);
    thread::scope(|s| {
        let handles: Vec<_> = data.chunks(size).map(|part| s.spawn(move || part.iter().sum::<u64>())).collect();
        handles.into_iter().map(|h| h.join().unwrap()).sum()
    })
}

fn parallel_map<T: Sync, R: Send>(items: &[T], threads: usize, f: impl Fn(&T) -> R + Sync) -> Vec<R> {
    let size = chunk_size(items.len(), threads);
    let f = &f;
    thread::scope(|s| {
        let handles: Vec<_> = items.chunks(size).map(|part| s.spawn(move || part.iter().map(f).collect::<Vec<R>>())).collect();
        handles.into_iter().flat_map(|h| h.join().unwrap()).collect()
    })
}

fn collect_messages(producers: usize, per_producer: usize) -> Vec<String> {
    let (tx, rx) = mpsc::channel();
    for i in 0..producers {
        let tx = tx.clone();
        thread::spawn(move || {
            for j in 0..per_producer {
                tx.send(format!("p{i}-{j}")).unwrap();
            }
        });
    }
    drop(tx);
    let mut all: Vec<String> = rx.iter().collect();
    all.sort();
    all
}

unitTests:
let data: Vec<u64> = (1..=100_000).collect();

test("parallel sum", || {
    check_eq(parallel_sum(&data, 4), 5_000_050_000);
    check_eq(parallel_sum(&data, 1), 5_000_050_000);
    check_eq(parallel_sum(&data[..3], 8), 6);
    check_eq(parallel_sum(&[], 3), 0);
    check_panics(|| { parallel_sum(&[1], 0); });
});

test("parallel map keeps order", || {
    let words = ["alpha", "be", "gamma", "d", "epsilon"];
    check_eq(parallel_map(&words, 2, |w| w.len()), vec![5, 2, 5, 1, 7]);
    let squares = parallel_map(&data, 3, |&x| x * x);
    check_eq(squares.len(), 100_000);
    check_eq(squares[99_999], 10_000_000_000);
    check_eq(parallel_map(&[] as &[u8], 2, |&b| b), Vec::<u8>::new());
});

test("messages from many producers", || {
    let all = collect_messages(3, 2);
    check_eq(all, vec!["p0-0", "p0-1", "p1-0", "p1-1", "p2-0", "p2-1"]);
    check_eq(collect_messages(5, 100).len(), 500);
    check_eq(collect_messages(0, 10).len(), 0);
});

